// Logistic regression fan-fault detector (normal = 0, fault = 1)
// Generated by logistic_regression.ipynb (shared split, C = 10.0).
// Features come from features.py. Input: 1000 samples at 1 kHz of the acceleration
// magnitude sqrt(ax^2 + ay^2 + az^2) in m/s^2 (raw counts * 9.80665 / 4096, +/-8 g range).
// Feature order MUST be:
//   rms, peak, std, kurtosis, crest_factor, band_5_25hz, band_25_75hz, band_75_200hz, band_200_500hz
// kurtosis = excess kurtosis (m4 / m2^2 - 3); crest_factor = peak / rms;
// band_* = mean over FFT bins in [lo, hi) Hz of (2 * |FFT(x - mean)| / N)^2.
#pragma once
#include <math.h>

#define N_FEATURES 9

static const float LR_MEAN[N_FEATURES] = {
  9.20654964e+00f, 9.62341118e+00f, 1.90294906e-01f,
  -3.49870950e-01f, 1.04525602e+00f, 3.73594339e-05f,
  2.02450249e-03f, 1.26572791e-04f, 1.36364242e-05f
};

static const float LR_SCALE[N_FEATURES] = {
  8.13969318e-03f, 2.93839633e-01f, 1.57366410e-01f,
  2.13093424e+00f, 3.11235432e-02f, 9.89711407e-05f,
  3.45658627e-03f, 5.66731796e-05f, 5.78329627e-06f
};

static const float LR_COEF[N_FEATURES] = {
  -1.95772719e+00f, 1.64189780e+00f, 9.96296823e-01f,
  -5.49726486e+00f, 1.74451625e+00f, 5.33352971e-01f,
  -4.70000766e-02f, 2.97478819e+00f, 1.05243826e+01f
};

static const float LR_INTERCEPT = 1.05851440e+01f;

// Returns the probability that the window is a fault.
static inline float lr_predict_proba(const float *x) {
  float s = LR_INTERCEPT;
  for (int i = 0; i < N_FEATURES; i++) s += LR_COEF[i] * (x[i] - LR_MEAN[i]) / LR_SCALE[i];
  return 1.0f / (1.0f + expf(-s));
}
